   position: fixed;
   inset: 0;
   z-index: 50;
   border: 0;
   padding: 0;
   background: rgba(0, 0, 0, 0.55);
   backdrop-filter: blur(2px);
   cursor: default;
 }

 /* ------------------------------------------------------------------ */
